  assert.equal(total(lines(10)), 950); // 1000 * 0.95
  assert.equal(total(lines(9)), 900); // below the threshold: no bulk discount
});

test('total applies customer and bulk discounts once each', () => {
  // 1000 * 0.9 * 0.95
  assert.equal(total(lines(10), 0.1), 855);
});

